// Isolated browser QA with fictional records and a generated PNG test sheet.
import {createClient as createCoreClient} from './notifications-client.js';
const PROJECT='22222222-2222-4222-8222-222222222222',DOC='33333333-3333-4333-8333-333333333333',REV='44444444-4444-4444-8444-444444444444',FOLDER='55555555-5555-4555-8555-555555555555',NOTE='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',OWNER='11111111-1111-4111-8111-111111111111';
const png='';
const bytes=Uint8Array.from(atob(png),c=>c.charCodeAt(0));
const docs=[{id:DOC,project_id:PROJECT,folder_id:FOLDER,code:'ARQ-001',title:'Implantação de arquitetura'},...Array.from({length:27},(_,i)=>({id:`10000000-0000-4000-8000-${String(i).padStart(12,'0')}`,project_id:PROJECT,folder_id:FOLDER,code:`QA-${String(i).padStart(3,'0')}`,title:`Implantação fictícia de arquitetura ${i}`}))];
const revisions=[{id:REV,project_id:PROJECT,document_id:DOC,revision_code:'R00',original_filename:'implantacao_prancha.png',mime_type:'image/png',file_size:bytes.length,object_path:'fixture.png',upload_state:'ready',created_by:OWNER,created_at:'2026-11-03T10:00:00Z'}];
const notes=[{id:NOTE,project_id:PROJECT,revision_id:REV,page_number:1,x:.45,y:.4,body:'Conferir implantação do acesso',kind:'pin',geometry:{points:[{x:.45,y:.4}]},status:'open',created_by:OWNER,author_name:'Pessoa fictícia',created_at:'2026-11-03T10:00:00Z',updated_at:'2026-11-03T10:00:00Z',deleted_at:null}];
const tables={documents:docs,document_revisions:revisions,document_annotations:notes,revision_reviews:[],folders:[{id:FOLDER,project_id:PROJECT,parent_id:null,name:'Arquitetura fictícia'}]};
class Query{constructor(table){this.table=table;this.filters=[];this.orders=[];}select(){return this;}eq(k,v){this.filters.push(r=>r[k]===v);return this;}in(k,v){this.filters.push(r=>v.includes(r[k]));return this;}is(k,v){this.filters.push(r=>(r[k]??null)===v);return this;}order(k,{ascending=true}={}){this.orders.push([k,ascending]);return this;}range(a,b){this.window=[a,b];return this;}maybeSingle(){this.one=true;return this;}single(){this.one=true;return this;}then(resolve,reject){let rows=tables[this.table].filter(r=>this.filters.every(f=>f(r)));rows.sort((a,b)=>{for(const [k,asc] of this.orders){const d=String(a[k]).localeCompare(String(b[k]));if(d)return d*(asc?1:-1);}return 0;});if(this.window)rows=rows.slice(this.window[0],this.window[1]+1);return Promise.resolve({data:structuredClone(this.one?rows[0]||null:rows),error:null}).then(resolve,reject);}}
const normalize=t=>String(t||'').normalize('NFD').replace(/\p{M}/gu,'').toLowerCase();
export function createClient(){const client=createCoreClient(),from=client.from,rpc=client.rpc;client.from=table=>Object.hasOwn(tables,table)?new Query(table):from(table);client.storage={from(){return {async download(){return {data:new Blob([bytes],{type:'image/png'}),error:null};}};}};
 client.rpc=async(name,args={})=>{
  if(name!=='search_project_content')return rpc(name,args);
  const tasks=(await from('project_tasks').select('*')).data;
  const base={project_id:PROJECT,project_code:'QA-001',project_name:'Projeto fictício de homologação',archived:false},hits=[];
  for(const d of docs)hits.push({...base,id:d.id,result_key:`document:${d.id}`,kind:'document',title:`${d.code} · ${d.title}`,excerpt:'',document_id:d.id,status:null,haystack:`${d.code} ${d.title}`});
  for(const r of revisions){const d=docs.find(d=>d.id===r.document_id);hits.push({...base,id:r.id,result_key:`revision:${r.id}`,kind:'revision',title:`${d.code} · ${d.title} · ${r.revision_code}`,excerpt:r.original_filename,document_id:d.id,revision_id:r.id,status:r.upload_state,haystack:`${d.code} ${d.title} ${r.revision_code} ${r.original_filename}`});}
  for(const t of tasks)hits.push({...base,id:t.id,result_key:`task:${t.id}`,kind:'task',title:`TAR-${String(t.task_number).padStart(6,'0')} · ${t.title}`,excerpt:t.description,status:t.stage,haystack:`${t.title} ${t.description}`});
  for(const a of notes)hits.push({...base,id:a.id,result_key:`annotation:${a.id}`,kind:'annotation',title:'ARQ-001 · R00 · página 1',excerpt:a.body,status:a.status,document_id:DOC,revision_id:REV,page_number:1,haystack:a.body});
  const matched=hits.filter(h=>(!args.p_project_id||h.project_id===args.p_project_id)&&(args.p_kind==='all'||h.kind===args.p_kind)&&normalize(h.haystack).includes(normalize(args.p_query))).sort((a,b)=>a.result_key<b.result_key?-1:1),page=matched.filter(h=>!args.p_after||h.result_key>args.p_after).slice(0,26),items=page.slice(0,25).map(({haystack,...h})=>h);
  return {data:{items,total:matched.length,has_more:page.length>25,next_cursor:items.at(-1)?.result_key||null},error:null};
 };return client;}
